    edges: [["base","prompt"],["prompt","rag"],["rag","ft"],["ft","pre"],["rag","distill"],["prompt","eval"],["rag","eval"],["ft","eval"]],
    details: {
      base: { role: "出発点となる汎用の基盤モデル（Gemini/Claude/GPT/Llama等）。", tech: "モデル選定＝品質・単価・レイテンシ・ライセンスの比較。", biz: "多くの用途は、この汎用モデルにプロンプトとRAGを足すだけで足りる。", qa: "最初にすべきは？（→自社タスクで汎用モデルの素の実力を測る。それが基準線）", cost: "汎用API利用が最も安く速い出発点。", roleEn: "The starting general-purpose foundation model (Gemini/Claude/GPT/Llama, etc.).", techEn: "Model choice = comparing quality, unit price, latency, license.", bizEn: "Most uses need only this general model plus prompting and RAG.", qaEn: "What should you do first? (→ measure the general model's raw ability on your task — that's the baseline)", costEn: "Using a general API is the cheapest, fastest starting point." },
      prompt: { role: "第1段：プロンプト設計で挙動を引き出す。最も安く速い。", tech: "指示の明確化、few-shot例、構造化出力、思考連鎖。", biz: "多くの「精度が出ない」はここで解決する。コストほぼゼロで試せる。", qa: "プロンプトで解けない問題は？（→知識不足はRAG、口調・形式の固定化はFTへ）", cost: "追加コストほぼゼロ。まずここを尽くす。", roleEn: "Step 1: draw out behavior via prompt design — cheapest and fastest.", techEn: "Clear instructions, few-shot, structured output, chain-of-thought.", bizEn: "Many 'accuracy' problems resolve here; you can try it at near-zero cost.", qaEn: "What can't prompting solve? (→ knowledge gaps go to RAG; fixing tone/format goes to fine-tuning)", costEn: "Near-zero added cost; exhaust this first." },
      rag: { role: "第2段：外部知識を検索して与える。知識を足したい時の第一選択。", tech: "埋め込み・検索・文脈投入。①のRAG図面が詳細。", biz: "社内知識の反映はほぼこれで足りる。再学習不要で最新情報を扱える。", qa: "RAGとFTの使い分けは？（→知識を足すならRAG、挙動を変えるならFT）", cost: "初期構築は安く、知識更新は差分再埋め込みで済む。", roleEn: "Step 2: retrieve and supply external knowledge — first choice when adding knowledge.", techEn: "Embedding, retrieval, context injection. See the RAG diagram.", bizEn: "Reflecting internal knowledge is mostly this — no retraining, handles fresh info.", qaEn: "RAG vs fine-tuning? (→ RAG to add knowledge; fine-tuning to change behavior)", costEn: "Cheap initial build; knowledge updates are just delta re-embedding." },
      ft: { role: "第3段：重みを更新し挙動・形式・専門性を変える。", tech: "SFT→DPO、多くはLoRAで省資源に。⑥の学習図面が詳細。", biz: "「口調・出力形式・特定タスク特化」を変えたい時。知識注入には非効率。", qa: "FTすべき時は？（→プロンプトとRAGで届かない挙動変更が要る時だけ）", cost: "データ整形と学習の人件費。知識をFTで入れると更新の度に再学習地獄。", roleEn: "Step 3: update weights to change behavior, format, specialization.", techEn: "SFT → DPO, often LoRA for efficiency. See the training diagram.", bizEn: "For changing tone/output format/task specialization; inefficient for injecting knowledge.", qaEn: "When should you fine-tune? (→ only when a behavior change beyond prompting and RAG is needed)", costEn: "Labor for data prep and training; injecting knowledge via FT means retraining hell on every update." },
      distill: { role: "第3'段：大型の品質を保ったまま小型化し原価を下げる。", tech: "教師モデルの出力で生徒を学習。定型・高頻度タスク向け。", biz: "量が出る定型処理を小型化して原価を桁で下げる「量産」の手段。", qa: "蒸留が効くタスクは？（→大量に流れる定型処理。未知の難問には不向き）", cost: "初期投資はかかるが、以降の推論単価を大きく下げる。", roleEn: "Step 3': shrink while preserving large-model quality to cut cost.", techEn: "Train a student on teacher outputs; for routine, high-frequency tasks.", bizEn: "A 'mass-production' means to shrink high-volume routine work and cut cost by an order.", qaEn: "Which tasks suit distillation? (→ high-volume routine work; poor for unseen hard problems)", costEn: "Upfront investment, but greatly lowers subsequent inference unit cost." },
      pre: { role: "第4段：ゼロから事前学習。コスト・データ・専門性が桁違い。", tech: "巨大コーパス、分散学習（FSDP/3D並列）、数億〜円規模。", biz: "選択肢の最後尾。「事前学習から提案する会社は疑え」と言えるのが階段を知る証。", qa: "自社事前学習が正当化される時は？（→ほぼ無い。汎用+RAG/FTが優ることが大半）", cost: "最も高価。BloombergGPTの教訓＝多くは汎用回帰。", roleEn: "Step 4: pretrain from scratch — cost, data, expertise are orders larger.", techEn: "Huge corpus, distributed training (FSDP/3D parallel), hundreds-of-millions scale.", bizEn: "The last resort. Saying 'be skeptical of vendors who open with pretraining' proves you know the staircase.", qaEn: "When is self-pretraining justified? (→ almost never; general + RAG/FT usually wins)", costEn: "The most expensive; the BloombergGPT lesson = most revert to general models." },
      eval: { role: "全段階に共通で必要な評価。これなしの改善は博打。", tech: "ゴールデンセット、自動評価、回帰テスト。⑦のLLMOps図面が詳細。", biz: "どの段でも「良くなったか」を数字で言えること。評価が投資判断の土台。", qa: "評価はいつ作る？（→カスタマイズに着手する前。基準線がないと効果を語れない）", cost: "評価基盤は資産。一度作れば全段階の改善判断を支える。", roleEn: "Evaluation needed at every step; improving without it is a gamble.", techEn: "Golden set, automated eval, regression tests. See the LLMOps diagram.", bizEn: "At any step, state 'did it improve' in numbers; eval is the foundation of investment decisions.", qaEn: "When do you build eval? (→ before starting customization; without a baseline you can't argue effect)", costEn: "An eval platform is an asset; once built, it supports decisions at every step." }
    }
