    edges: [["q","emb"],["emb","ann"],["q","bm25"],["ann","fusion"],["bm25","fusion"],["fusion","rerank"],["emb","quant"],["fusion","filter"]],
    details: {
      q: { role: "検索したい質問。まず意味ベクトルへ変換する。", tech: "クエリ書き換え、意図分類、HyDE等の前処理。", biz: "「検索がヒットしない」の多くはクエリ側の工夫で安く解決できる。", qa: "検索前にすべきことは？（→曖昧な質問の書き換え・拡張。安価で効果大）", cost: "クエリ前処理は小型モデルで十分。フロンティアは過剰。", roleEn: "The question to search; first converted to a meaning vector.", techEn: "Query rewriting, intent classification, HyDE preprocessing.", bizEn: "Most 'search doesn't hit' cases are cheaply fixed on the query side.", qaEn: "What to do before searching? (→ rewrite/expand vague questions; cheap, high impact)", costEn: "Query preprocessing needs only a small model; frontier is overkill." },
      emb: { role: "テキストを意味ベクトルへ写像する。", tech: "埋め込みモデル選定、多言語対応、次元数。", biz: "検索の「舌」。モデル更新時は全再埋め込みが要る点を先に握る。", qa: "埋め込みモデル更新で何が起きる？（→ベクトル空間が変わり、全再インデックスが必要）", cost: "百万トークン単位の従量。バッチAPIで単価を下げる。", roleEn: "Maps text into meaning vectors.", techEn: "Embedding-model choice, multilingual support, dimensionality.", bizEn: "Search's 'tongue.' Nail down upfront that a model update requires full re-embedding.", qaEn: "What happens on an embedding-model update? (→ the vector space changes; full re-indexing is needed)", costEn: "Per-token billing in the millions; batch APIs lower unit cost." },
      ann: { role: "近似最近傍検索で高速に近いベクトルを見つける。", tech: "HNSW（近傍グラフ）/IVF（クラスタ分割）、efSearch調整。", biz: "全探索は非現実的。近似で速度と精度を両立するのが実務。", qa: "efSearchを上げると？（→recall向上とQPS低下のトレードオフ）", cost: "索引の種類とパラメータで、メモリ・速度・精度が変わる。", roleEn: "Finds near vectors fast via approximate nearest neighbor.", techEn: "HNSW (neighbor graph) / IVF (cluster split), efSearch tuning.", bizEn: "Exhaustive search is impractical; approximation balances speed and accuracy in practice.", qaEn: "What if you raise efSearch? (→ higher recall, lower QPS — a trade-off)", costEn: "Index type and parameters shape memory, speed, and accuracy." },
      bm25: { role: "字面（キーワード）一致で検索する古典手法。", tech: "転置インデックス、TF-IDF系スコアリング。", biz: "固有名詞・型番はベクトルが苦手。BM25併用で穴を塞ぐ。", qa: "なぜベクトルだけでは不十分？（→型番等の字面一致に弱い。BM25で補完）", cost: "軽量で安価。ハイブリッドの片翼として費用対効果が高い。", roleEn: "Classic keyword (literal-match) search.", techEn: "Inverted index, TF-IDF-family scoring.", bizEn: "Vectors struggle with proper nouns and model numbers; BM25 plugs the gap.", qaEn: "Why aren't vectors alone enough? (→ weak on literal matches like part numbers; complement with BM25)", costEn: "Lightweight and cheap; cost-effective as one wing of hybrid search." },
      fusion: { role: "意味検索と字面検索の結果を統合する。", tech: "RRF（順位の逆数和）、重み付け（α調整）。", biz: "スケールの違うスコアを順位ベースで頑健に融合する定石。", qa: "RRFの利点は？（→スコアのスケール差に頑健。順位の逆数で融合）", cost: "融合ロジックは軽量。精度を底上げする安い一手。", roleEn: "Merges semantic and literal search results.", techEn: "RRF (reciprocal rank fusion), weighting (alpha tuning).", bizEn: "The standard for robustly fusing differently-scaled scores by rank.", qaEn: "Benefit of RRF? (→ robust to score-scale differences; fuses via reciprocal rank)", costEn: "Fusion logic is lightweight — a cheap move that lifts accuracy." },
      rerank: { role: "候補を精密に並べ替え、上位の質を高める。", tech: "クロスエンコーダ。クエリと文書を同時に処理。", biz: "「あと一歩」の精度が要る時の定番投資。まず評価してから入れる。", qa: "リランカーを入れる判断は？（→top-k内に正解はあるが上位に来ない時）", cost: "呼び出し毎に100-300msの追加。UX予算との交換。", roleEn: "Precisely reorders candidates to raise top-result quality.", techEn: "Cross-encoder; processes query and document together.", bizEn: "The go-to investment when you need that last bit of precision; evaluate before adding.", qaEn: "When to add a reranker? (→ when the answer is in top-k but not ranked at the top)", costEn: "Adds 100–300ms per call; traded against the UX budget." },
      quant: { role: "ベクトルを量子化しメモリを圧縮する。", tech: "スカラー量子化、積量子化（PQ）、精度検証。", biz: "1億ベクトル級ではメモリが高価。量子化で数%の精度と引き換えに圧縮。", qa: "量子化の代償は？（→検索精度が数%低下。許容できるか検証してから）", cost: "メモリを1/4等に削減し、常駐コストを大きく下げる。", roleEn: "Quantizes vectors to compress memory.", techEn: "Scalar quantization, product quantization (PQ), accuracy validation.", bizEn: "At 100M-vector scale memory is costly; quantize, trading a few % accuracy for compression.", qaEn: "What's the cost of quantization? (→ a few % drop in accuracy; verify it's acceptable first)", costEn: "Cuts memory to ~1/4, greatly lowering resident cost." },
      filter: { role: "権限・日付等で候補を事前/事後に絞る。", tech: "メタデータフィルタ、ACL伝播、時間減衰。", biz: "「見てよい文書だけ検索」を保証。エンタープライズRAGの必須要件。", qa: "権限をどう反映？（→ユーザー権限を検索段でフィルタし、越権閲覧を防ぐ）", cost: "フィルタ設計が、情報漏えいという最大リスクを防ぐ。", roleEn: "Narrows candidates by permission, date, etc., pre/post search.", techEn: "Metadata filters, ACL propagation, time decay.", bizEn: "Guarantees 'search only documents you may see' — an enterprise-RAG must.", qaEn: "How do you reflect permissions? (→ filter by user permission at retrieval to prevent over-privileged reads)", costEn: "Filter design prevents the biggest risk — information leakage." }
    }
