      inscan: { role: "既知の攻撃パターンを一次スクリーニングする。", tech: "分類器、パターン検知、ジェイルブレイク検出。", biz: "補助的防御。単層では破られる前提で、あくまで一層目。", qa: "入力検査だけで十分？（→否。検知は破られる。構造で守る多層防御が要る）", cost: "軽量な一次フィルタ。単独では不十分だが有効。", roleEn: "First-pass screening of known attack patterns.", techEn: "Classifiers, pattern detection, jailbreak detection.", bizEn: "Auxiliary defense; assume a single layer is breakable — this is only the first.", qaEn: "Is input scanning enough? (→ no; detection gets broken. You need structural defense-in-depth)", costEn: "A lightweight first filter; effective but insufficient alone." },
      sep: { role: "命令とデータを分離し、データに実行力を与えない。", tech: "信頼境界、spotlighting、構造的分離。", biz: "間接注入への本質的防御。フィルタ追加でなく構造で守る。", qa: "間接注入の本質的対策は？（→信頼できないデータを指示として実行させない構造）", cost: "構造的防御は、検知に頼るより根本的で堅い。", roleEn: "Separates instructions from data; gives no execution power to data.", techEn: "Trust boundaries, spotlighting, structural separation.", bizEn: "The essential defense against indirect injection; defend by structure, not more filters.", qaEn: "Essential countermeasure to indirect injection? (→ a structure that won't execute untrusted data as instructions)", costEn: "Structural defense is more fundamental and robust than relying on detection." },
      perm: { role: "エージェントの権限を必要最小に絞る。", tech: "スコープ付きトークン、読み取り専用既定、承認ゲート。", biz: "侵害されても被害を局限する。権限設計が爆風半径。", qa: "最小権限が守るものは？（→侵害時の被害範囲。権限が小さいほど被害も小さい）", cost: "権限を絞ることは無料で、事故時の損失を大きく減らす。", roleEn: "Narrows the agent's permissions to the minimum necessary.", techEn: "Scoped tokens, read-only by default, approval gates.", bizEn: "Limits damage even if breached; permission design is the blast radius.", qaEn: "What does least privilege protect? (→ the scope of breach damage; smaller permissions, smaller damage)", costEn: "Narrowing permissions is free and greatly reduces incident loss." },
      llm: { role: "処理の中心。ここが騙されると全体に波及する。", tech: "システムプロンプトの堅牢化、機密を指示に埋めない。", biz: "system promptは漏れる前提。機密情報をそこに置かない。", qa: "プロンプトリークへの備えは？（→機密を指示に埋めず、出力も検査する）", cost: "モデル自体の堅牢化と、周辺の多層防御を組み合わせる。", roleEn: "The processing core; if fooled here, it ripples through everything.", techEn: "Hardening the system prompt, not embedding secrets in instructions.", bizEn: "Assume the system prompt leaks; don't put secrets there.", qaEn: "How do you guard against prompt leaks? (→ don't embed secrets in instructions, and inspect outputs)", costEn: "Combine model hardening with surrounding defense-in-depth." },
      outscan: { role: "生成物の有害・機密・幻覚を出す前に検査する。", tech: "出力フィルタ、PII検知、引用照合、出力エンコード。", biz: "出す前の最終関門。下流での不正実行（XSS等）も防ぐ。", qa: "出力検査で防ぐものは？（→有害出力、PII漏えい、下流での注入実行）", cost: "追加検査の費用より、事故の損失が遥かに大きい。", roleEn: "Inspects outputs for harmful/confidential/hallucinated content before release.", techEn: "Output filters, PII detection, citation matching, output encoding.", bizEn: "The final gate before release; also prevents downstream misexecution (XSS, etc.).", qaEn: "What does output scanning prevent? (→ harmful output, PII leaks, downstream injection execution)", costEn: "The cost of extra inspection is far less than the loss from an incident." },
